T Volume() const {
    Vector3<T> d = Diagonal();
    return d.x * d.y * d.z;
}

int MaxDimension() const {
    Vector3<T> d = Diagonal();
    if (d.x > d.y && d.x > d.z) return 0;
    else if (d.y > d.z)         return 1;
    else                        return 2;
}

