    Float m[N][N];
};

static SquareMatrix Zero() {
    SquareMatrix m;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            m.m[i][j] = 0;
    return m;
}

SquareMatrix operator+(const SquareMatrix &m) const {
    SquareMatrix r = *this;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            r.m[i][j] += m.m[i][j];
    return r;
}

template <typename Tresult, int N, typename T>
Tresult Mul(const SquareMatrix<N> &m, const T &v) {
    Tresult result;
    for (int i = 0; i < N; ++i) {
        result[i] = 0;
        for (int j = 0; j < N; ++j)
            result[i] += m[i][j] * v[j];
    }
    return result;
}

